/** Inline SVG icon for a topic (decorative: aria-hidden). */
export function topicIcon(id, size = 24) {
  return `<svg class="ticon" viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${ICON_PATHS[id] || ''}</svg>`;
}

/** SVG markup as a standalone image (used to draw icons on the share-card canvas). */
export function topicIconDataUrl(id, color) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="96" height="96" fill="none" stroke="${color}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ICON_PATHS[id] || ''}</svg>`;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

/** CSS custom properties for one topic, applied inline on a card or chip. */
export function topicVars(id) {
  const t = TOPIC_STYLE[id];
  if (!t) return '';
  return `--t-accent:${t.accent};--t-mid:${t.mid};--t-tint:${t.tint};--t-dark-accent:${t.darkAccent};--t-dark-tint:${t.darkTint}`;
}
